custom_css:
@font-face {
    font-family: "Outfit Variable";
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
    src: url("https://fonts.gstatic.com/s/outfit/v15/QGYvz_MVcBeNP4NJuktqQ4E.woff2") format("woff2");
    unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF;
}

@font-face {
    font-family: "Outfit Variable";
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
    src: url("https://fonts.gstatic.com/s/outfit/v15/QGYvz_MVcBeNP4NJtEtq.woff2") format("woff2");
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

body[data-path^="dispatch-register"] {
    --font-stack: "Outfit Variable", sans-serif;
    font-family: "Outfit Variable", sans-serif;
    font-size: 16px;
}

body[data-path^="dispatch-register"] main.container {
    width: calc(100vw - 48px) !important;
    max-width: calc(100vw - 48px) !important;
    margin-left: auto;
    margin-right: auto;
}

body[data-path^="dispatch-register"] .page_content,
body[data-path^="dispatch-register"] .web-form-container,
body[data-path^="dispatch-register"] .web-form {
    width: 100% !important;
    max-width: none !important;
}

body[data-path^="dispatch-register"] .web-form {
    border: 0 !important;
    box-shadow: none !important;
    border-radius: 0 !important;
}

body[data-path^="dispatch-register"] .page_content,
body[data-path^="dispatch-register"] .web-form,
body[data-path^="dispatch-register"] .web-form-introduction,
body[data-path^="dispatch-register"] .form-control,
body[data-path^="dispatch-register"] input,
body[data-path^="dispatch-register"] select,
body[data-path^="dispatch-register"] textarea,
body[data-path^="dispatch-register"] button {
    font-family: "Outfit Variable", sans-serif !important;
    font-size: 16px;
}

body[data-path^="dispatch-register"] h1,
body[data-path^="dispatch-register"] .web-form-title h1 {
    font-family: "Outfit Variable", sans-serif !important;
    font-size: 44px !important;
    line-height: 1.1;
}

body[data-path^="dispatch-register"] h2 {
    font-family: "Outfit Variable", sans-serif !important;
    font-size: 22px !important;
    line-height: 1.25;
}

body[data-path^="dispatch-register"] code,
body[data-path^="dispatch-register"] pre,
body[data-path^="dispatch-register"] kbd,
body[data-path^="dispatch-register"] samp {
    font-family: "Outfit Variable", sans-serif !important;
    font-size: 14px !important;
}

body[data-path^="dispatch-register"] .web-form-footer .submit-btn,
body[data-path^="dispatch-register"] .web-form .btn-primary {
    background-color: #f97316 !important;
    border-color: #f97316 !important;
    color: #ffffff !important;
}

body[data-path^="dispatch-register"] .web-form-footer .submit-btn:hover,
body[data-path^="dispatch-register"] .web-form-footer .submit-btn:focus,
body[data-path^="dispatch-register"] .web-form .btn-primary:hover,
body[data-path^="dispatch-register"] .web-form .btn-primary:focus {
    background-color: #ea580c !important;
    border-color: #ea580c !important;
    color: #ffffff !important;
}

body[data-path^="dispatch-register"] .form-grid {
    overflow: visible !important;
}

body[data-path^="dispatch-register"] .awesomplete > ul {
    min-width: 320px;
    z-index: 1060 !important;
}

@media (max-width: 1024px) {
    body[data-path^="dispatch-register"],
    body[data-path^="dispatch-register"] .page_content,
    body[data-path^="dispatch-register"] .web-form,
    body[data-path^="dispatch-register"] .web-form-introduction,
    body[data-path^="dispatch-register"] .form-control,
    body[data-path^="dispatch-register"] input,
    body[data-path^="dispatch-register"] select,
    body[data-path^="dispatch-register"] textarea,
    body[data-path^="dispatch-register"] button {
        font-size: 15px;
    }

    body[data-path^="dispatch-register"] h1,
    body[data-path^="dispatch-register"] .web-form-title h1 {
        font-size: 32px !important;
    }

    body[data-path^="dispatch-register"] h2 {
        font-size: 18px !important;
    }

    body[data-path^="dispatch-register"] code,
    body[data-path^="dispatch-register"] pre,
    body[data-path^="dispatch-register"] kbd,
    body[data-path^="dispatch-register"] samp {
        font-size: 14px !important;
    }
}

@media (max-width: 767px) {
    body[data-path^="dispatch-register"] main.container {
        width: 100% !important;
        max-width: 100% !important;
        padding-left: 12px;
        padding-right: 12px;
    }
}
/* Floating Delivery Note dropdown */
body[data-path^="dispatch-register"] .dispatch-floating-link-options {
    position: fixed !important;
    right: auto !important;
    min-width: 0 !important;
    overflow-x: hidden !important;
    overflow-y: auto !important;
    z-index: 10050 !important;
    border-radius: 8px;
    box-shadow: 0 12px 32px rgba(15, 23, 42, 0.22);
}

body[data-path^="dispatch-register"] .dispatch-floating-link-options > li {
    white-space: normal;
    overflow-wrap: anywhere;
}

/* Responsive dispatch table */
body[data-path^="dispatch-register"] {
    max-width: 100%;
    overflow-x: hidden;
}

body[data-path^="dispatch-register"] .page-content-wrapper,
body[data-path^="dispatch-register"] .page_content,
body[data-path^="dispatch-register"] .web-form-container,
body[data-path^="dispatch-register"] .web-form,
body[data-path^="dispatch-register"] .web-form-body,
body[data-path^="dispatch-register"] .web-form-wrapper {
    min-width: 0;
    max-width: 100%;
    box-sizing: border-box;
}

@media (max-width: 1024px) {
    body[data-path^="dispatch-register"] main.container {
        width: 100% !important;
        max-width: 100% !important;
        padding-left: 16px;
        padding-right: 16px;
    }

    body[data-path^="dispatch-register"] .web-form-title,
    body[data-path^="dispatch-register"] .web-form-title h1,
    body[data-path^="dispatch-register"] .web-form-introduction,
    body[data-path^="dispatch-register"] .web-form-introduction p {
        max-width: 100%;
        white-space: normal !important;
        overflow-wrap: anywhere;
    }

    body[data-path^="dispatch-register"] .form-grid-container {
        display: block;
        width: 100%;
        max-width: 100%;
        overflow-x: auto !important;
        overscroll-behavior-inline: contain;
        -webkit-overflow-scrolling: touch;
        scrollbar-gutter: stable;
    }

    body[data-path^="dispatch-register"] .form-grid {
        position: static !important;
        left: 0 !important;
        width: 1100px !important;
        min-width: 1100px !important;
        max-width: none !important;
        overflow: visible !important;
    }

    body[data-path^="dispatch-register"] .grid-heading-row,
    body[data-path^="dispatch-register"] .grid-body .data-row {
        width: 100% !important;
        min-width: 1100px !important;
    }

    body[data-path^="dispatch-register"] .web-form-footer .web-form-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
    }
}

@media (max-width: 767px) {
    body[data-path^="dispatch-register"] main.container {
        padding-left: 12px;
        padding-right: 12px;
    }

    body[data-path^="dispatch-register"] .web-form {
        padding-left: 0 !important;
        padding-right: 0 !important;
    }

    body[data-path^="dispatch-register"] .form-grid-container {
        padding-bottom: 4px;
    }

    body[data-path^="dispatch-register"] .web-form-footer .right-area {
        display: flex;
        width: 100%;
        justify-content: flex-end;
    }
}
